INSERT INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-08-03' FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'en', 'Dual model — real-time clearance or same-day reporting (General Department of Taxation)', 'This deep-dive page reflects publicly available GDT guidance and industry reporting as of August 2026 and is provided for general awareness, not legal or tax advice. Penalty enforcement practice and threshold details continue to evolve — confirm current requirements directly with the General Department of Taxation or your integration provider before building against them.', 'Vietnam''s e-invoicing framework was established by Decree 123/2020/ND-CP in December 2020, piloted across six provinces and cities including Hanoi and Ho Chi Minh City from November 2021, and became compulsory nationwide on 1 July 2022, when paper invoices ceased to have legal validity for VAT purposes. Decree 70/2025/ND-CP, effective June 2025, then expanded the mandate to large business households and foreign e-commerce suppliers.', 'Invoices are authored as structured XML per General Department of Taxation (GDT) technical standards. A digital signature is required on every invoice except those issued from POS cash registers, which are waived the signature requirement but generate a unique QR/tax code instead.', 'The mandate covers domestic B2B, B2C retail, B2G, and export sales for all registered businesses since July 2022, with business households and individual businesses above a VND 1 billion annual-revenue threshold brought into scope for POS e-invoicing since June 2025 — alongside consumer-facing sectors (retail, hospitality, transport, personal services) regardless of revenue. Imports are not subject to e-invoice issuance by the importer.', 'Getting compliant means integrating an e-invoicing solution, working out which of the two transmission models applies to your invoices, and — for business households and consumer-facing sectors — checking whether the POS e-invoicing threshold applies to you.', 'Vietnam''s penalty framework, restructured under Decree 310/2025/ND-CP from 16 January 2026, scales fines by the count of violating invoices found within an inspection period rather than a flat or percentage figure — a single late invoice draws a modest fine, but the same violation repeated across 100 or more invoices draws a fine tens of times larger.', 'Vietnam''s e-invoicing mandate has been compulsory nationwide since 1 July 2022, with two coexisting transmission models — real-time clearance with a General Department of Taxation (GDT) code, or same-day reporting without one. Decree 70/2025/ND-CP expanded coverage in June 2025 to large business households (VND 1 billion+ revenue) and foreign e-commerce suppliers, and a restructured, violation-count-scaled penalty framework took effect in January 2026.', '🇻🇳' FROM countries WHERE name_en = 'Vietnam';
