INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Format & standard', '[["Authoring format", "Structured XML, per GDT technical standards"], ["Digital signature", "Required, except POS cash-register invoices"], ["Verification artifact", "GDT-issued code (real-time clearance) or a same-day transmission record (reporting model)"], ["Legal basis", "Decree 123/2020/ND-CP, amended by Decree 70/2025/ND-CP; Circular 78/2021/TT-BTC guidance"]]', 'Every invoice is XML regardless of which transmission model applies — the two models differ in when and how the GDT sees the data, not in the invoice''s own format.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Identifiers & registration', '[["Taxpayer identity", "Vietnamese tax identification number (MST)"], ["Access routes", "In-house system, a certified service provider, or the GDT''s own e-invoice portal"], ["Transmission platform", "General Department of Taxation (GDT) centralized system"], ["Foreign suppliers", "Digital/e-commerce suppliers with no permanent Vietnamese establishment may register directly since June 2025"]]', 'The foreign-supplier registration route is new with Decree 70/2025 — before it, a non-resident digital supplier had no direct path to issuing a compliant Vietnamese VAT invoice at all.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Mandatory content & archiving', '[["Party data", "Seller and buyer tax identification numbers"], ["Invoice types", "VAT invoices or sales invoices, depending on the seller''s tax method"], ["POS invoices", "Real-time transmission, signature waived, unique QR/tax code generated"], ["Retention period", "10 years, in original electronic (XML) form with digital signatures intact"]]', 'Ten years is a longer retention duty than most countries in this tracker require — plan archive infrastructure accordingly, whether kept in-house or with a certified provider (offshore storage is permitted under data-security conditions).', NULL);
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 0, 'pills' FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'Model 1 — real-time clearance (with a GDT code)', 'When an invoice is issued under the coded model, it follows this sequence:', 'Nothing reaches the buyer until the GDT has issued the code — a genuine clearance model, the same shape as Jordan and Israel elsewhere in this tracker.');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Invoice drafted in XML');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 1, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Submitted to the GDT for a code');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 2, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'GDT issues the verification code');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 3, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Coded invoice delivered to buyer');
INSERT INTO deep_dive_lifecycle_cards (country_id, section, sort_order, display_style) SELECT id, 'scope_transmission', 1, 'pills' FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 'en', 'Model 2 — same-day reporting (without a code)', 'When an invoice is issued under the uncoded model, it instead follows this sequence:', 'This is the flow most similar to South Korea''s post-issuance model elsewhere in this tracker — the invoice is valid on delivery, and reporting to the tax authority is a parallel duty due no later than the same day, not a precondition for validity.');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 0, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Invoice issued and delivered to buyer');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 1, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'Data sent to the GDT, same day at latest');
INSERT INTO deep_dive_lifecycle_statuses_v2 (card_id, sort_order, is_special) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_cards), 2, 0);
INSERT INTO deep_dive_lifecycle_status_v2_translations (status_id, lang, label) VALUES ((SELECT MAX(id) FROM deep_dive_lifecycle_statuses_v2), 'en', 'GDT cross-checks the reported data');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'Who''s in scope, and since when', '[["All registered businesses", "Mandatory since 1 July 2022"], ["Business households/individuals ≥ VND 1 billion revenue", "POS e-invoicing mandatory since June 2025"], ["Consumer-facing sectors (retail, hospitality, transport, personal services)", "POS e-invoicing mandatory regardless of revenue, since June 2025"], ["Foreign digital/e-commerce suppliers", "May register directly since June 2025 (voluntary)"]]', 'The consumer-facing-sector rule is a real exception to Vietnam''s otherwise revenue-based threshold — a small restaurant or hair salon is in scope even well under VND 1 billion in annual revenue.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 3 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'What''s covered', '[["Domestic B2B", "Covered"], ["B2C retail", "Covered"], ["B2G", "Covered"], ["Exports", "Covered — invoice due by the next working day after customs clearance"], ["Imports", "Not covered — no e-invoice issuance duty on the importer"]]', 'Vietnam''s scope is genuinely broad — domestic and cross-border sales, retail and government contracts alike — with imports as the one explicit carve-out, since the duty sits with the seller, not the buyer.', NULL);
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Incorrect issuance timing — 1 violating invoice', 'VND 500,000 – 1.5 million', NULL);
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'Incorrect issuance timing — 100+ violating invoices', 'VND 50 – 70 million', NULL);
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'No invoice issued — 1 violating invoice', 'VND 1 – 2 million', NULL);
INSERT INTO deep_dive_penalty_rows (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) VALUES ((SELECT MAX(id) FROM deep_dive_penalty_rows), 'en', 'No invoice issued — 100+ violating invoices', 'VND 60 – 80 million', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📊 Penalties scale with volume, not just severity', NULL, NULL, 'Vietnam''s fine schedule escalates by the count of violating invoices found within an inspection period, not a flat or percentage figure — a single late or missing invoice draws a modest fine, while the same violation across 100 or more invoices draws a fine tens of times larger. Multiple violations on the same day count as a single penalty at the highest applicable tier, not one penalty per invoice.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '🧾 Two invoice tracks, two penalty tables', NULL, NULL, 'Revenue-generating sales (goods and services) carry a separate, generally higher fine table than non-commercial or internal-use invoices — promotions, samples, gifts, internal consumption, and lending/borrowing arrangements sit on their own, lighter schedule. The table above reflects the revenue-generating track.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📅 A tightened, restructured framework since January 2026', NULL, NULL, 'Decree 310/2025/ND-CP replaced the prior flat-fine structure with the violation-count-scaled schedule above, effective 16 January 2026 — the underlying e-invoicing mandate itself didn''t change, but the cost of getting it wrong at scale did.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your e-invoicing solution is integrated', 'Every registered business needs a system routing invoices to the GDT — direct API, in-house software, or a certified service provider — since paper invoices have had no legal validity since July 2022.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Determine which transmission model applies to your invoices', 'Work out whether your invoices need a GDT-issued code before delivery (real-time clearance) or same-day reporting without one, and configure your systems for the correct flow.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Business households and individual businesses: check the VND 1 billion threshold', 'If your annual revenue meets or exceeds VND 1 billion, register a POS cash register connected to the GDT — and check the consumer-facing-sector rule too, which applies regardless of revenue.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Foreign digital suppliers: consider direct VAT-invoice registration', 'Since June 2025, foreign e-commerce and digital-service suppliers without a Vietnamese establishment can register to issue Vietnamese VAT invoices directly rather than relying on a local intermediary.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Match invoice-issuance timing to the transaction type', 'Goods: at transfer of ownership or usage rights. Services: on completion. Exports: by the next working day after customs clearance. Utilities: by the 7th day of the following month.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Vietnam';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Archive every invoice for 10 years in its original XML form', 'Retention runs longer here than in most countries this tracker covers — keep the signed XML itself, not just a PDF rendering, whether stored in-house or with a certified provider.');
